parameters.jsCode:
// ============================================================
// Validate token + schema_version + required payload fields.
// Throws on invalid input — n8n returns 500 to TradingView.
// On success: passes the parsed payload as $json downstream.
//
// SECURITY NOTE: webhook secret is hardcoded as a string literal.
// n8n cloud does NOT expose $env.* to Code nodes. If your plan
// supports the Variables panel, swap the literal for:
//   const EXPECTED_TOKEN = $vars.SOCRATES_WEBHOOK_TOKEN;
//
// REPLACE THE PLACEHOLDER BELOW with your real webhook secret.
// Do NOT commit the real secret to git — leave the placeholder
// in the committed JSON, set the actual value only inside n8n.
// ============================================================

const EXPECTED_TOKEN = 'REPLACE_WITH_YOUR_WEBHOOK_SECRET';
if (EXPECTED_TOKEN === 'REPLACE_WITH_YOUR_WEBHOOK_SECRET') {
  throw new Error('Webhook token not configured — replace placeholder string in Validate & Auth node');
}

const item   = $input.item.json;
const query  = item.query  || {};
const body   = item.body   || item;          // n8n may flatten

// 1. Auth
if (query.token !== EXPECTED_TOKEN) {
  throw new Error('401: invalid or missing ?token query param');
}

// 2. Schema version
if (body.schema_version !== '1.0') {
  throw new Error(`400: unsupported schema_version: ${body.schema_version}`);
}

// 3. Required fields
const required = [
  'alert_id', 'timestamp_utc', 'timestamp_et', 'symbol', 'timeframe',
  'setup_type', 'grade', 'direction', 'price', 'stop_price'
];
for (const k of required) {
  if (body[k] === undefined || body[k] === null) {
    throw new Error(`400: missing required field: ${k}`);
  }
}

// 4. Grade sanity
if (!['A+', 'A', 'B', 'C'].includes(body.grade)) {
  throw new Error(`400: invalid grade: ${body.grade}`);
}

return { json: body };

// Merge the upsert result + release window check + original payload
// from the Validate step into a single object for downstream nodes.

const upsert   = $('Upsert into socrates.alerts').item.json;  // {alert_id, grade, ts_et, is_new}
const release  = $input.item.json;                            // {in_release_window: bool}
const payload  = $('Validate & Auth').item.json;              // full alert payload

const inRelease  = release.in_release_window === true;
const gradeIsC   = upsert.grade === 'C';
const shouldSend = !inRelease && !gradeIsC;

return {
  json: {
    ...payload,
    _alert_id: upsert.alert_id,
    _in_release_window: inRelease,
    _grade_is_c: gradeIsC,
    _should_send_telegram: shouldSend
  }
};

// ============================================================
// Build Telegram message body (HTML mode — minimal escaping).
// Grade dictates emoji + notification settings downstream.
//
// NOTE: chat_id hardcoded here because n8n cloud blocks $env.*
// from Code nodes. If your plan supports Variables panel, you
// can switch to `const chatId = $vars.SOCRATES_TELEGRAM_CHAT_ID;`
// ============================================================

const p = $input.item.json;

function esc(s) {
  if (s === undefined || s === null) return '';
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function fmtNum(n, dp = 2) {
  return typeof n === 'number' ? n.toFixed(dp) : esc(n);
}

// Snake_case → Title Case, with trading-domain abbreviations kept
// uppercase and tokens like '4h' / '5m' getting the letter uppercased.
const ABBREVIATIONS = new Set([
  'ICT','NY','ON','RTH','PDH','PDL','ONH','ONL','VIX','NQ','ES','GC','MGC',
  'DXY','SPY','NVDA','QQQ','AVWAP','EMA','ATR','VWAP','TF','ET','UTC','AM','PM'
]);
function prettify(s) {
  if (s === undefined || s === null) return '';
  return String(s)
    .replace(/_/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 0)
    .map(word => {
      const upper = word.toUpperCase();
      if (ABBREVIATIONS.has(upper)) return upper;
      if (/^\d+[a-zA-Z]+$/.test(word)) {
        return word.replace(/[a-zA-Z]+/, m => m.toUpperCase());
      }
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    })
    .join(' ');
}

const gradeEmoji = ({ 'A+': '🟢', 'A': '🔵', 'B': '⚪' })[p.grade] || '·';
const dirColor   = p.direction === 'long' ? '🟢' : '🔴';
const dirArrow   = p.direction === 'long' ? '▲' : '▼';
const dirText    = p.direction.toUpperCase();

const lines = [];
lines.push(`${gradeEmoji} <b>${esc(p.symbol)}</b> · <b>${esc(p.grade)}</b> · ${dirColor} ${dirArrow} <b>${dirText}</b> @ <code>${fmtNum(p.price)}</code>`);
lines.push(`<i>Setup ${esc(p.setup_type)} — ${esc(p.setup_name || '')}</i>`);
lines.push('');
lines.push(`<b>Stop</b>   <code>${fmtNum(p.stop_price)}</code>   (${fmtNum(p.stop_distance_points)} pts · $${fmtNum(p.stop_distance_dollars_per_contract)}/contract)`);
if (p.target_1 !== null && p.target_1 !== undefined) {
  lines.push(`<b>T1</b>     <code>${fmtNum(p.target_1)}</code>   ($${fmtNum(p.target_1_dollars_per_contract)}/contract)`);
}
if (p.target_2 !== null && p.target_2 !== undefined) {
  lines.push(`<b>T2</b>     <code>${fmtNum(p.target_2)}</code>`);
}
lines.push('');
if (p.confluences && p.confluences.length) {
  const pretty = p.confluences.map(prettify).join(', ');
  lines.push(`<b>Confluences:</b> ${esc(pretty)}`);
}
if (p.volume) {
  lines.push(`<b>Vol:</b> Bull ${esc(p.volume.bull_pct)} / Bear ${esc(p.volume.bear_pct)} · ${fmtNum(p.volume.bar_volume_vs_20avg)}× 20-bar avg${p.volume.flip_detected ? ' · Flip' : ''}`);
}
if (p.session) {
  const sessWindow = prettify(p.session.window);
  const ictZone    = prettify(p.session.ict_zone || '');
  lines.push(`<b>Session:</b> ${esc(sessWindow)}${ictZone ? ' · ' + esc(ictZone) : ''}`);
}
lines.push('');
lines.push(`<code>${esc(p.alert_id)}</code>`);

const silent = p.grade === 'B';
const chatId = '-1003961335144';

return {
  json: {
    _alert_id: p._alert_id,
    _chat_id: chatId,
    _text: lines.join('\n'),
    _silent: silent,
    _parse_mode: 'HTML'
  }
};

parameters.query:
update socrates.alerts
   set release_window_check = true
 where alert_id = $1;
